"""Isolated local scientific computation; neither a provider nor physical evidence.

Only a copied public workspace is host-mounted. Scratch is an isolated tmpfs
(legacy) or an owned ephemeral Docker volume (Spark). Resource policy is explicit
and receipt-bound; the historical bounded policy remains the default. Docker is an operational isolation boundary,
not a formal security proof. The caller retains scientific schema/adoption gates.
"""

from __future__ import annotations

import hashlib
import json
import os
import selectors
import shutil
import stat
import subprocess
import tarfile
import tempfile
import time
import uuid
from pathlib import Path, PurePosixPath

IMAGE = os.environ.get("NDFEB_SCIENCE_IMAGE", "sha256:3ec04370f5f2226b968133bf3054548c51a54769bbaa6874baa905759962df10")
DOCKER = shutil.which("docker") or "docker"
TIMEOUT_SECONDS = 45.0
MAX_SOURCE_BYTES = 8 * 1024 * 1024
MAX_INPUT_BYTES = 8 * 1024 * 1024
MAX_FILE_BYTES = 4 * 1024 * 1024
MAX_FILES = 128
MAX_LOG_BYTES = 64 * 1024
MAX_RESULT_BYTES = 4 * 1024 * 1024
# Room for a legal RESULT plus escaped binary logs and bounded scratch/export
# metadata. The result and each retained log are still validated separately.
MAX_WIRE_BYTES = 4 * MAX_RESULT_BYTES + 16 * MAX_LOG_BYTES


def resource_policy():
    """Resolve an explicit owner configuration, never investigator-supplied code.

    No job-count or wall-clock budget is imposed by spark-science-v1. Physical
    capacity and host contention still exist; callers must freeze this identity
    alongside the image and executor hashes before a counted episode.
    """
    profile = os.environ.get("NDFEB_SCIENCE_PROFILE", "legacy-bounded-v1")
    if profile == "legacy-bounded-v1":
        return {"profile": profile, "cpus": 1, "memory_bytes": 1073741824,
                "pids_limit": 32, "timeout_seconds": TIMEOUT_SECONDS, "gpus": None,
                "scratch_size": "32m", "scratch_file_bytes": MAX_FILE_BYTES,
                "blas_threads": None, "scratch_inventory_limit": MAX_FILES, "oom_score_adj": None}
    if profile == "spark-science-v1":
        return {"profile": profile, "cpus": None, "memory_bytes": None,
                "pids_limit": None, "timeout_seconds": None, "gpus": "all",
                "scratch_size": None, "scratch_file_bytes": None,
                "blas_threads": max(1, os.cpu_count() or 1),
                "scratch_inventory_limit": MAX_FILES, "oom_score_adj": 1000}
    raise WorkspaceRejected("Unknown NDFEB_SCIENCE_PROFILE: " + profile)


# This exact source is included in every receipt. stdout is the untrusted JSON
# transport, not an authority channel. Python's -I isolates interpreter startup;
# the investigator retains unrestricted stdlib inside the container boundary.
RUNNER = r'''
import contextlib
import errno
import hashlib
import importlib.util
import io
import json
import os
from pathlib import Path
import resource
import sys
import traceback
import threading

LOG_LIMIT = 65536
RESULT_LIMIT = 4194304
FILE_LIMIT = 4194304
SPARK_RESOURCES = False
if not SPARK_RESOURCES:
    resource.setrlimit(resource.RLIMIT_FSIZE, (FILE_LIMIT, FILE_LIMIT))
resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
if not SPARK_RESOURCES:
    resource.setrlimit(resource.RLIMIT_NOFILE, (128, 128))
os.chdir('/scratch')
sys.path.insert(0, '/workspace')

class OutputLimit(Exception):
    pass

class BoundedText(io.TextIOBase):
    def __init__(self):
        self.parts = []
        self.size = 0
        self.truncated = False
    def writable(self):
        return True
    def write(self, value):
        value = str(value)
        data = value.encode('utf-8', 'replace')
        remaining = LOG_LIMIT - self.size
        if remaining > 0:
            self.parts.append(data[:remaining])
        self.size += min(len(data), remaining)
        if len(data) > remaining:
            self.truncated = True
            if not SPARK_RESOURCES:
                raise OutputLimit('stdout/stderr byte limit exceeded')
        return len(value)
    def value(self):
        return b''.join(self.parts).decode('utf-8', 'replace').encode('utf-8')[:LOG_LIMIT].decode('utf-8', 'ignore')

class NativeCapture:
    """Drain native/subprocess fd writes without exposing the JSON channel."""
    def __init__(self, fd):
        self.parts = []
        self.size = 0
        self.truncated = False
        self.lock = threading.Lock()
        self.read_fd, write_fd = os.pipe()
        os.dup2(write_fd, fd)
        os.close(write_fd)
        self.thread = threading.Thread(target=self.drain, daemon=True)
        self.thread.start()
    def drain(self):
        try:
            while block := os.read(self.read_fd, 65536):
                with self.lock:
                    remaining = LOG_LIMIT - self.size
                    if remaining > 0:
                        self.parts.append(block[:remaining])
                    self.size += min(len(block), remaining)
                    if len(block) > remaining:
                        self.truncated = True
        except OSError:
            with self.lock:
                self.truncated = True
        finally:
            os.close(self.read_fd)
    def finish(self, target):
        # A caller that leaves a background child running must not hold the
        # envelope hostage. The container will stop remaining children on exit.
        self.thread.join(timeout=1)
        with self.lock:
            if self.thread.is_alive():
                self.truncated = True
            raw = b''.join(self.parts)
            text = raw.decode('utf8', 'replace').encode('utf8')[:LOG_LIMIT].decode('utf8', 'ignore')
            target.write(text)
            target.truncated = target.truncated or self.truncated

protocol_fd = os.dup(1) if SPARK_RESOURCES else None
native_captures = [NativeCapture(1), NativeCapture(2)] if SPARK_RESOURCES else []

out, err = BoundedText(), BoundedText()
result = None
status = 'execution_error'
reason = None
scratch_files = []
scratch_inventory_truncated = False
exported_files = []
try:
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        payload = json.loads(Path('/workspace/__executor_payload__.json').read_text())
        program = Path('/workspace/__executor_program__.py')
        if program.exists():
            namespace = {'payload': payload, '__name__': '__main__'}
            exec(compile(program.read_text(), str(program), 'exec'), namespace)
            if 'RESULT' not in namespace:
                raise ValueError('Investigator test program must define RESULT')
            result = namespace['RESULT']
        else:
            spec = importlib.util.spec_from_file_location('investigator_model', '/workspace/model.py')
            model = importlib.util.module_from_spec(spec)
            sys.modules['investigator_model'] = model
            spec.loader.exec_module(model)
            result = model.forecast(payload)
        if (out.truncated or err.truncated) and not SPARK_RESOURCES:
            raise OutputLimit('An output limit was caught by investigator code; execution remains limited')
        encoded = json.dumps(result, sort_keys=True, separators=(',', ':'), allow_nan=False)
        if len(encoded.encode()) > RESULT_LIMIT:
            raise OutputLimit('RESULT JSON byte limit exceeded')
        if not isinstance(result, dict):
            raise ValueError('RESULT/forecast must return a JSON object')
        if SPARK_RESOURCES:
            requested = result.get('artifact_paths', [])
            if not isinstance(requested, list) or len(requested) > 128:
                raise ValueError('RESULT.artifact_paths must be a list of at most128 relative paths')
            seen = set()
            for name in requested:
                if (not isinstance(name, str) or not name or Path(name).is_absolute()
                        or '..' in Path(name).parts or Path(name).as_posix() != name
                        or name in seen or name == '.'):
                    raise ValueError('Invalid or duplicate artifact path')
                seen.add(name)
                target = Path('/scratch') / name
                if target.is_symlink() or not target.is_file() or any(
                        parent.is_symlink() for parent in target.parents if parent != Path('/')):
                    raise ValueError('Artifact must be a regular file without symlinks')
                hasher = hashlib.sha256()
                with target.open('rb') as stream:
                    while block := stream.read(1048576):
                        hasher.update(block)
                exported_files.append({'path': name, 'bytes': target.stat().st_size,
                                       'sha256': hasher.hexdigest()})
        for parent, dirs, files in os.walk('/scratch', followlinks=False):
            for name in dirs + files:
                path = Path(parent) / name
                if path.is_symlink():
                    if SPARK_RESOURCES:
                        scratch_inventory_truncated = True
                        continue
                    raise OutputLimit('Scratch symlinks are not exported')
            for name in files:
                path = Path(parent) / name
                if SPARK_RESOURCES and (path.is_symlink() or not path.is_file()):
                    scratch_inventory_truncated = True
                    continue
                if len(scratch_files) >= 128:
                    if SPARK_RESOURCES:
                        scratch_inventory_truncated = True
                        continue
                    raise OutputLimit('Scratch output-file count limit exceeded')
                size = path.stat().st_size
                if size > FILE_LIMIT and not SPARK_RESOURCES:
                    raise OutputLimit('Scratch output-file byte limit exceeded')
                hasher = hashlib.sha256()
                with path.open('rb') as stream:
                    while block := stream.read(1048576):
                        hasher.update(block)
                scratch_files.append({'path': str(path.relative_to('/scratch')), 'bytes': size,
                    'sha256': hasher.hexdigest()})
        status = 'ok'
except BaseException as exc:
    if isinstance(exc, OutputLimit) or (isinstance(exc, OSError) and exc.errno in (errno.EFBIG, errno.ENOSPC)):
        status = 'output_limit'
    reason = type(exc).__name__ + ': ' + str(exc)[:2048]
    result = None
    try:
        err.write(traceback.format_exc(limit=8))
    except BaseException:
        pass
if SPARK_RESOURCES:
    # Flush Python bypass streams and C stdio before closing capture writers.
    for stream in (sys.__stdout__, sys.__stderr__):
        try:
            stream.flush()
        except (OSError, ValueError):
            pass
    try:
        import ctypes
        ctypes.CDLL(None).fflush(None)
    except (OSError, AttributeError):
        pass
    null_fd = os.open(os.devnull, os.O_WRONLY)
    os.dup2(null_fd, 1)
    os.dup2(null_fd, 2)
    os.close(null_fd)
    for capture, target in zip(native_captures, (out, err)):
        capture.finish(target)
envelope = {'status': status, 'result': result, 'reason': reason,
            'stdout': out.value(), 'stderr': err.value(), 'scratch_files': scratch_files,
            'scratch_inventory_truncated': scratch_inventory_truncated, 'exported_files': exported_files,
            'stdout_truncated': out.truncated, 'stderr_truncated': err.truncated,
            'runtime': {'python': sys.version.split()[0], 'uid': os.getuid(),
                        'evidence_class': 'investigator_computation',
                        'oom_score_adj': Path('/proc/self/oom_score_adj').read_text().strip(),
                        'file_descriptor_limits': list(resource.getrlimit(resource.RLIMIT_NOFILE)),
                        'file_size_limits': list(resource.getrlimit(resource.RLIMIT_FSIZE)),
                        'effective_cgroup': {name: Path('/sys/fs/cgroup/' + name).read_text().strip()
                            for name in ('cpu.max', 'memory.max', 'pids.max')
                            if Path('/sys/fs/cgroup/' + name).is_file()}}}
encoded_envelope = json.dumps(envelope, sort_keys=True, separators=(',', ':'),
                              ensure_ascii=False, allow_nan=False)
if SPARK_RESOURCES:
    with os.fdopen(protocol_fd, 'w', encoding='utf8') as transport:
        transport.write(encoded_envelope)
        transport.flush()
else:
    sys.__stdout__.write(encoded_envelope)
    sys.__stdout__.flush()
'''


class WorkspaceRejected(ValueError):
    """The proposed public filesystem is not safe to snapshot/mount."""


def _json_bytes(value):
    return (json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False) + "\n").encode()


def _sha(data):
    return hashlib.sha256(data).hexdigest()


def _decode_limited(data):
    return data[:MAX_LOG_BYTES].decode('utf-8', 'replace').encode('utf-8')[:MAX_LOG_BYTES].decode('utf-8', 'ignore')


def _save_json(path, value):
    path.write_bytes(_json_bytes(value))


def _bindings(value, *, payload=False):
    """Validate caller-owned bindings, never a manifest read from model files."""
    if value is None:
        return {}
    if not isinstance(value, dict):
        raise WorkspaceRejected('Public data bindings must be an object')
    for name, expected in value.items():
        if (not isinstance(name, str) or not isinstance(expected, str)
                or len(expected) != 64 or any(c not in '0123456789abcdef' for c in expected)):
            raise WorkspaceRejected('Invalid public data hash binding')
        if payload:
            if name not in {'evidence', 'investigation_state'}:
                raise WorkspaceRejected('Only owner evidence/state payload fields may be bound')
        elif (not name or name == '.' or PurePosixPath(name).is_absolute()
              or '..' in PurePosixPath(name).parts or PurePosixPath(name).as_posix() != name
              or any(part.startswith('__executor_') for part in PurePosixPath(name).parts)):
            raise WorkspaceRejected('Invalid public data path binding')
    return dict(value)


def _snapshot(workspace, destination, trusted_files=None):
    """Copy through no-follow directory descriptors; reject links/devices/FIFOs."""
    if workspace.is_symlink() or not workspace.is_dir():
        raise WorkspaceRejected("Workspace must be a real directory, not a symlink")
    manifest = {}
    total = 0
    directory_count = 0
    file_count = 0
    trusted = _bindings(trusted_files)
    missing = set(trusted)
    public_directories = {parent.as_posix() for name in trusted for parent in PurePosixPath(name).parents
                          if parent.as_posix() != '.'}

    def copy_directory(fd, relative):
        nonlocal total, directory_count, file_count
        directory_count += relative.as_posix() not in public_directories
        if directory_count > MAX_FILES:
            raise WorkspaceRejected("Workspace directory count limit exceeded")
        for name in sorted(os.listdir(fd)):
            if name.startswith("__executor_"):
                raise WorkspaceRejected("Reserved executor filename: " + name)
            info = os.stat(name, dir_fd=fd, follow_symlinks=False)
            target = relative / name
            if (trusted_files is not None and target.parts[0] in {'sources', 'reference_sources', 'evidence_curves'}
                    and target.as_posix() not in trusted and target.as_posix() not in public_directories):
                raise WorkspaceRejected('Unlisted file/directory in protected namespace: ' + target.as_posix())
            if stat.S_ISDIR(info.st_mode):
                child = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
                try:
                    (destination / target).mkdir()
                    (destination / target).chmod(0o755)
                    copy_directory(child, target)
                finally:
                    os.close(child)
            elif stat.S_ISREG(info.st_mode) and info.st_nlink == 1:
                public = target.as_posix() in trusted
                if not public and (file_count >= MAX_FILES or info.st_size > MAX_FILE_BYTES):
                    raise WorkspaceRejected("Workspace file size/count limit exceeded")
                child = os.open(name, os.O_RDONLY | os.O_NOFOLLOW, dir_fd=fd)
                try:
                    opened = os.fstat(child)
                    if not stat.S_ISREG(opened.st_mode) or opened.st_nlink != 1:
                        raise WorkspaceRejected("File changed to a link or special file")
                    if not public and opened.st_size > MAX_FILE_BYTES:
                        raise WorkspaceRejected('Workspace file size limit exceeded')
                    length, hasher = 0, hashlib.sha256()
                    with os.fdopen(child, "rb", closefd=False) as stream, (destination / target).open('xb') as copied:
                        while block := stream.read(min(262144, opened.st_size - length + 1)):
                            length += len(block)
                            if length > opened.st_size:
                                raise WorkspaceRejected('File grew during snapshot')
                            if not public and (length > MAX_FILE_BYTES or total + length > MAX_SOURCE_BYTES):
                                raise WorkspaceRejected('Workspace byte limit exceeded')
                            hasher.update(block)
                            copied.write(block)
                    if length != opened.st_size:
                        raise WorkspaceRejected('File shrank during snapshot')
                finally:
                    os.close(child)
                if public:
                    if hasher.hexdigest() != trusted[target.as_posix()]:
                        raise WorkspaceRejected('Public evidence hash mismatch: ' + target.as_posix())
                    missing.remove(target.as_posix())
                else:
                    total += length
                    file_count += 1
                (destination / target).chmod(0o444)
                manifest[target.as_posix()] = {"sha256": hasher.hexdigest(), "bytes": length}
            else:
                raise WorkspaceRejected("Links and special files are prohibited: " + target.as_posix())
    root_fd = os.open(workspace, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        copy_directory(root_fd, Path())
    finally:
        os.close(root_fd)
    if missing:
        raise WorkspaceRejected('Missing bound public files: ' + ', '.join(sorted(missing)[:5]))
    return manifest


_LEGACY_TIMEOUT = object()


def _run_bounded(command, container_name, timeout_seconds=_LEGACY_TIMEOUT):
    if timeout_seconds is _LEGACY_TIMEOUT:
        timeout_seconds = TIMEOUT_SECONDS
    process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    selector = selectors.DefaultSelector()
    for stream in (process.stdout, process.stderr):
        os.set_blocking(stream.fileno(), False)
        selector.register(stream, selectors.EVENT_READ)
    captured = {process.stdout: bytearray(), process.stderr: bytearray()}
    stop_reason = None
    start = time.monotonic()
    try:
        while selector.get_map():
            if timeout_seconds is not None and time.monotonic() - start > timeout_seconds:
                stop_reason = "timeout"
                break
            for key, _ in selector.select(timeout=0.05):
                block = os.read(key.fileobj.fileno(), 65536)
                if not block:
                    selector.unregister(key.fileobj)
                    continue
                cap = MAX_WIRE_BYTES if key.fileobj is process.stdout else MAX_LOG_BYTES
                target = captured[key.fileobj]
                remaining = cap - len(target)
                # One overflow byte distinguishes exact-limit logs from truncation.
                target.extend(block[:remaining + 1])
                if len(block) > remaining:
                    stop_reason = "output_limit"
                    break
            if stop_reason:
                break
        if stop_reason:
            # Exact generated name is the only cleanup target; no broad prune.
            # Detach the local backpressured log reader first. Otherwise a
            # stdout-flooding process can delay Docker's attach teardown.
            process.kill()
            process.wait(timeout=5)
            try:
                subprocess.run([DOCKER, "rm", "--force", "--volumes", container_name], capture_output=True, timeout=10, check=False)
            except subprocess.TimeoutExpired:
                pass  # execute() independently confirms final exact-name cleanup.
        process.wait(timeout=10 if timeout_seconds is not None else None)
    finally:
        selector.close()
        for stream in (process.stdout, process.stderr):
            stream.close()
        if process.poll() is None:
            process.kill()
            process.wait(timeout=5)
    return stop_reason, process.returncode, bytes(captured[process.stdout]), bytes(captured[process.stderr])



def _export_artifacts(container_name, envelope, run_dir):
    """Stream only declared regular artifacts to generated owner paths.

    Never extract archive names onto the host. The container has finished, so
    its processes cannot rewrite an exported file while it is being verified.
    No bytes are injected into the model context; the caller admits these as
    computational artifacts, never physical measurements.
    """
    expected = envelope.get("exported_files", [])
    requested = envelope["result"].get("artifact_paths", [])
    if (not isinstance(expected, list) or not isinstance(requested, list) or len(expected) > MAX_FILES
            or any(not isinstance(item, dict) for item in expected)):
        raise ValueError("Invalid artifact export manifest")
    if [item.get("path") for item in expected if isinstance(item, dict)] != requested:
        raise ValueError("Artifact export manifest does not match requested paths")
    seen = set()
    exported = []
    for index, item in enumerate(expected):
        name = item.get("path")
        size, digest = item.get("bytes"), item.get("sha256")
        if (not isinstance(name, str) or not name or name == "." or PurePosixPath(name).is_absolute()
                or ".." in PurePosixPath(name).parts or PurePosixPath(name).as_posix() != name
                or name in seen or not isinstance(size, int) or isinstance(size, bool) or size < 0
                or not isinstance(digest, str) or len(digest) != 64
                or any(c not in "0123456789abcdef" for c in digest)):
            raise ValueError("Invalid artifact export identity")
        seen.add(name)
        destination = run_dir / "exported"
        destination.mkdir(exist_ok=True)
        filename = f"{index:04d}-{uuid.uuid4().hex}"
        target = destination / filename
        partial = target.with_suffix(".partial")
        with tempfile.TemporaryFile() as errors:
            process = subprocess.Popen([DOCKER, "cp", container_name + ":/tmp/" + name, "-"],
                                       stdout=subprocess.PIPE, stderr=errors)
            try:
                members = 0
                with tarfile.open(fileobj=process.stdout, mode="r|*") as archive:
                    for member in archive:
                        members += 1
                        if (members != 1 or not member.isfile() or member.linkname
                                or member.name != PurePosixPath(name).name or member.size != size):
                            raise ValueError("Artifact archive must contain exactly its declared regular file")
                        stream = archive.extractfile(member)
                        hasher, written = hashlib.sha256(), 0
                        with partial.open("xb") as output:
                            while block := stream.read(1048576):
                                written += len(block)
                                if written > size:
                                    raise ValueError("Artifact grew during export")
                                output.write(block)
                                hasher.update(block)
                        if written != size or hasher.hexdigest() != digest:
                            raise ValueError("Artifact export content hash or size mismatch")
                process.stdout.close()
                if process.wait() != 0 or members != 1:
                    errors.seek(0)
                    raise ValueError("Artifact export failed: " + errors.read(MAX_LOG_BYTES).decode("utf8", "replace"))
                partial.replace(target)
                target.chmod(0o444)
            finally:
                if process.poll() is None:
                    process.kill()
                    process.wait(timeout=5)
                process.stdout.close()
        exported.append({"path": name, "sha256": digest, "bytes": size,
                         "receipt_relative_path": target.relative_to(run_dir).as_posix()})
    return exported


def execute(workspace: Path, payload: dict, receipt_dir: Path, code: str | None = None,
            *, trusted_files=None, trusted_payload_fields=None) -> dict:
    """Run one isolated numerical job with an explicit recorded resource policy.

    `code=None` imports public model.py and calls forecast(payload). Otherwise
    code runs with a payload global and must define a JSON-object RESULT. Status
    ok is JSON execution success only; the caller validates forecast schema.
    """
    started = time.monotonic()
    policy = resource_policy()
    spark = policy["profile"] == "spark-science-v1"
    runner = RUNNER.replace("SPARK_RESOURCES = False", "SPARK_RESOURCES = True").replace("/scratch", "/tmp") if spark else RUNNER
    if not (IMAGE.startswith("sha256:") and len(IMAGE) == 71 and all(c in "0123456789abcdef" for c in IMAGE[7:])):
        raise WorkspaceRejected("NDFEB_SCIENCE_IMAGE must be a pinned sha256 image ID")
    execution_id = "rpi-science-" + uuid.uuid4().hex
    workspace, receipt_dir = Path(workspace), Path(receipt_dir)
    receipt_dir.mkdir(parents=True, exist_ok=True)
    run_dir = receipt_dir / execution_id
    run_dir.mkdir(mode=0o755)
    snapshot = run_dir / "workspace"
    snapshot.mkdir(mode=0o755)
    restrictions = {
        "image": IMAGE, "pull": "never", "network": "none", "rootfs": "read_only",
        **policy, "uid_gid": "65534:65534",
        "cap_drop": "ALL", "no_new_privileges": True, "host_mounts": "public snapshot read-only only",
        "docker_log_driver": "none",
        "scratch": ("owned anonymous Docker volume at/tmp; shared host disk; no host bind" if spark else
                    "container tmpfs,32MiB,noexec/nosuid/nodev; no host scratch bind"),
        "max_log_bytes_each": MAX_LOG_BYTES,
        "python_log_overflow": "truncate_and_continue" if spark else "stop_execution",
        "native_log_overflow": "drain_truncate_and_continue" if spark else "stop_execution",
        "log_merge_order": "Python prefix followed by native prefix; not chronological" if spark else "Python only",
        "max_wire_bytes": MAX_WIRE_BYTES,
        "max_result_bytes": MAX_RESULT_BYTES, "max_output_files": MAX_FILES,
        "max_output_file_bytes": policy["scratch_file_bytes"], "secrets_forwarded": False,
        "scratch_export": ("RESULT.artifact_paths explicitly retained; other scratch content ephemeral" if spark else
                           "inventory only; scratch content is ephemeral"),
        "shared_host_capacity": policy["profile"] == "spark-science-v1",
    }
    result = {"execution_id": execution_id, "status": "rejected", "result": None,
              "stdout": "", "stderr": "", "container_restrictions": restrictions,
              "stdout_truncated": False, "stderr_truncated": False,
              "evidence_class": "investigator_computation", "receipt_dir": str(run_dir)}
    command = None
    try:
        if not isinstance(payload, dict):
            raise WorkspaceRejected("payload must be a JSON object")
        if workspace.resolve() in run_dir.resolve().parents:
            raise WorkspaceRejected("Receipt directory cannot be inside the public workspace")
        public_files = _bindings(trusted_files)
        public_fields = _bindings(trusted_payload_fields, payload=True)
        manifest = _snapshot(workspace, snapshot, public_files if trusted_files is not None else None)
        if code is None and "model.py" not in manifest:
            raise WorkspaceRejected("Default execution requires workspace/model.py")
        input_bytes = _json_bytes(payload)
        for name, expected in public_fields.items():
            if name not in payload or _sha(_json_bytes(payload[name])) != expected:
                raise WorkspaceRejected('Public payload hash mismatch: ' + name)
            relative = {'evidence': 'released_evidence.json', 'investigation_state': 'investigation_state.json'}[name]
            if relative not in public_files:
                raise WorkspaceRejected('Public payload requires its bound workspace file: ' + name)
            file_value = json.loads((snapshot / relative).read_text())
            if _sha(_json_bytes(file_value)) != expected:
                raise WorkspaceRejected('Public payload differs from bound workspace file: ' + name)
        untrusted_input = {name: value for name, value in payload.items() if name not in public_fields}
        if len(_json_bytes(untrusted_input)) > MAX_INPUT_BYTES:
            raise WorkspaceRejected("Input JSON byte limit exceeded")
        source = code.encode() if code is not None else (snapshot / "model.py").read_bytes()
        if len(source) > MAX_FILE_BYTES:
            raise WorkspaceRejected("Executed source byte limit exceeded")
        (run_dir / "input.json").write_bytes(input_bytes)
        (run_dir / "executed_source.py").write_bytes(source)
        (run_dir / "runner.py").write_text(runner)
        (snapshot / "__executor_payload__.json").write_bytes(input_bytes)
        (snapshot / "__executor_runner__.py").write_text(runner)
        if code is not None:
            (snapshot / "__executor_program__.py").write_bytes(source)
        for reserved in snapshot.glob('__executor_*'):
            reserved.chmod(0o444)
        _save_json(run_dir / "workspace_manifest.json", manifest)
        _save_json(run_dir / 'public_data_bindings.json', {'files': public_files, 'payload_fields': public_fields})
        restrictions['public_data_budget_basis'] = {
            'hash_bound_files_excluded_from_untrusted_snapshot_limits': len(public_files),
            'hash_bound_payload_fields_excluded_from_untrusted_input_limit': sorted(public_fields),
            'untrusted_snapshot_bytes': MAX_SOURCE_BYTES, 'untrusted_input_bytes': MAX_INPUT_BYTES,
            'boundary': 'Caller-owned immutable public data; security and recorded resource policy unchanged'}
        result["hashes"] = {"input_sha256": _sha(input_bytes), "executed_source_sha256": _sha(source),
                            "workspace_sha256": _sha(_json_bytes(manifest)), "runner_sha256": _sha(runner.encode()),
                            'public_data_bindings_sha256': _sha(_json_bytes({'files': public_files, 'payload_fields': public_fields})),
                            "executor_sha256": _sha(Path(__file__).read_bytes())}
        inspection = subprocess.run([DOCKER, "image", "inspect", IMAGE], capture_output=True, timeout=10, check=False)
        inspected = json.loads(inspection.stdout) if inspection.returncode == 0 else []
        if not inspected or inspected[0].get("Id") != IMAGE:
            raise WorkspaceRejected("Pinned existing image unavailable; no pull or fallback allowed")
        _save_json(run_dir / "image_identity.json", {key: inspected[0].get(key) for key in ("Id", "Architecture", "Os", "RepoDigests")})
        if policy["gpus"]:
            runtime_check = subprocess.run([DOCKER, "info", "--format", "{{json .Runtimes}}"],
                                           capture_output=True, timeout=10, check=False)
            runtimes = json.loads(runtime_check.stdout) if runtime_check.returncode == 0 else {}
            if "nvidia" not in runtimes:
                raise WorkspaceRejected("spark-science-v1 requires the installed NVIDIA Docker runtime; no CPU fallback")
        resource_flags = (["--memory=1g", "--memory-swap=1g", "--cpus=1", "--pids-limit=32"]
                          if policy["profile"] == "legacy-bounded-v1" else
                          ["--pids-limit=-1", "--gpus=all", "--oom-score-adj=1000", "--env=NVIDIA_DRIVER_CAPABILITIES=compute,utility",
                           "--env=OPENBLAS_NUM_THREADS=" + str(policy["blas_threads"]),
                           "--env=OMP_NUM_THREADS=" + str(policy["blas_threads"]),
                           "--env=MKL_NUM_THREADS=" + str(policy["blas_threads"])])
        command = [DOCKER, "run", "--pull=never", *([] if spark else ["--rm"]), "--name", execution_id,
                   "--log-driver=none",
                   "--network=none", "--read-only", *resource_flags, "--cap-drop=ALL", "--security-opt=no-new-privileges",
                   "--user=65534:65534", "--mount", "type=bind,src=" + str(snapshot.resolve()) + ",dst=/workspace,readonly",
                   *(["--mount", "type=volume,dst=/tmp"] if spark else
                     ["--tmpfs", "/scratch:rw,noexec,nosuid,nodev,size=32m,mode=1777"]),
                   "--workdir=" + ("/tmp" if spark else "/scratch"), "--env=PYTHONDONTWRITEBYTECODE=1", "--env=PYTHONHASHSEED=0",
                   "--env=TMPDIR=" + ("/tmp" if spark else "/scratch"), "--entrypoint=/usr/local/bin/python3", IMAGE,
                   "-I", "-B", "/workspace/__executor_runner__.py"]
        _save_json(run_dir / "command.json", command)
        stop, returncode, wire, errors = (_run_bounded(command, execution_id) if policy["profile"] == "legacy-bounded-v1"
                                          else _run_bounded(command, execution_id, timeout_seconds=None))
        (run_dir / "transport_stdout.bin").write_bytes(wire)
        (run_dir / "transport_stderr.bin").write_bytes(errors)
        result.update(returncode=returncode,
                      stdout_truncated=len(wire) > MAX_LOG_BYTES,
                      stderr_truncated=len(errors) > MAX_LOG_BYTES)
        if stop:
            result.update(status=stop, reason="Recoverable numerical execution " + stop,
                          stdout=_decode_limited(wire), stderr=_decode_limited(errors))
        elif returncode != 0:
            result.update(status="execution_error", reason="Container exited without successful transport",
                          stdout=_decode_limited(wire), stderr=_decode_limited(errors))
        else:
            try:
                envelope = json.loads(wire)
                if not isinstance(envelope, dict) or envelope.get("status") not in ("ok", "execution_error", "output_limit"):
                    raise ValueError("Invalid execution envelope")
                for key in ("stdout", "stderr"):
                    if not isinstance(envelope.get(key), str) or len(envelope[key].encode()) > MAX_LOG_BYTES:
                        raise ValueError("Invalid bounded logs")
                if envelope["status"] == "ok" and (not isinstance(envelope.get("result"), dict) or len(_json_bytes(envelope["result"])) > MAX_RESULT_BYTES + 1):
                    raise ValueError("Invalid bounded RESULT")
                if spark and envelope["status"] == "ok":
                    result["exported_artifacts"] = _export_artifacts(execution_id, envelope, run_dir)
                result.update({key: envelope.get(key) for key in ("status", "result", "reason", "stdout", "stderr", "stdout_truncated", "stderr_truncated", "scratch_files", "scratch_inventory_truncated", "runtime")})
            except (ValueError, TypeError) as exc:
                result.update(status="invalid_output", reason=str(exc),
                              stdout=_decode_limited(wire), stderr=_decode_limited(errors))
    except KeyboardInterrupt:
        result.update(status="interrupted", result=None, reason="Operator interrupted the numerical job; not a scientific outcome")
        raise
    except (WorkspaceRejected, OSError, ValueError, tarfile.TarError, subprocess.SubprocessError) as exc:
        result.update(status="rejected" if isinstance(exc, WorkspaceRejected) else "executor_error",
                      reason=type(exc).__name__ + ": " + str(exc)[:2048])
    finally:
        if command is not None:
            try:
                scratch_volumes = []
                volume_inspection_known = True
                if spark:
                    mount_check = subprocess.run([DOCKER, "container", "inspect", execution_id],
                                                 capture_output=True, timeout=10, check=False)
                    volume_inspection_known = mount_check.returncode == 0 or b'no such' in mount_check.stderr.lower()
                    result["scratch_volume_inspection"] = {"returncode": mount_check.returncode,
                        "container_absent": mount_check.returncode != 0 and b'no such' in mount_check.stderr.lower()}
                    if mount_check.returncode == 0:
                        owned = json.loads(mount_check.stdout)
                        scratch_volumes = [m["Name"] for c in owned for m in c.get("Mounts", [])
                                           if m.get("Type") == "volume" and m.get("Destination") == "/tmp"]
                cleanup = subprocess.run([DOCKER, "rm", "--force", "--volumes", execution_id], capture_output=True, timeout=10, check=False)
                if cleanup.returncode == 0:
                    result["cleanup"] = "removed"
                else:
                    check = subprocess.run([DOCKER, "container", "inspect", execution_id], capture_output=True, timeout=5, check=False)
                    result["cleanup"] = "confirmed_absent" if check.returncode != 0 and b'no such' in check.stderr.lower() else "unconfirmed"
                if spark:
                    volume_status = []
                    for volume in scratch_volumes:
                        check_volume = subprocess.run([DOCKER, "volume", "inspect", volume],
                                                      capture_output=True, timeout=10, check=False)
                        volume_status.append(check_volume.returncode != 0 and b'no such' in check_volume.stderr.lower())
                    result["scratch_volume_cleanup"] = {"owned_volumes": len(scratch_volumes),
                                                        "confirmed_absent": volume_inspection_known and all(volume_status)}
                    if not volume_inspection_known or not all(volume_status):
                        result["cleanup"] = "unconfirmed"
                if result["cleanup"] == "unconfirmed":
                    result.update(status="executor_error", reason="Owned container cleanup could not be confirmed", result=None)
            except (OSError, ValueError, TypeError, subprocess.SubprocessError):
                result["cleanup"] = "unconfirmed"
                result.update(status="executor_error", reason="Owned container cleanup could not be confirmed", result=None)
        result["duration_seconds"] = time.monotonic() - started
        (run_dir / "stdout.txt").write_text(result["stdout"])
        (run_dir / "stderr.txt").write_text(result["stderr"])
        if result.get("result") is not None:
            _save_json(run_dir / "result.json", result["result"])
            result["hashes"]["result_sha256"] = _sha((run_dir / "result.json").read_bytes())
        _save_json(run_dir / "receipt.json", result)
    return result
